    print(page)
    # assume page is list
    if isinstance(page,list):
        alarms.extend(page)
        if len(page)<20:
            break
    else:
        # if dict has alarms
        if 'alarms' in page:
            alarms.extend(page['alarms'])
            if len(page['alarms'])<20:
                break
        else:
            break
